/// Rayon-parallel native sweep over disjoint ip-ranges.
pub fn run_native_rayon(p: Ptrs, s: &Params, n: usize, chunk: usize) {
    use rayon::prelude::*;
    let nchunks = n.div_ceil(chunk);
    (0..nchunks).into_par_iter().for_each(|c| {
        let lo = c * chunk;
        let hi = ((c + 1) * chunk).min(n);
        unsafe {
            mgga_x_tpss_kxc_pol_range(
                p.rho as *const f64,
            p.sigma as *const f64,
            p.lapl as *const f64,
            p.tau as *const f64,
            p.zk,
            p.vrho,
            p.vsigma,
            p.vlapl,
            p.vtau,
            p.v2rho2,
            p.v2rhosigma,
            p.v2rholapl,
            p.v2rhotau,
            p.v2sigma2,
            p.v2sigmalapl,
            p.v2sigmatau,
            p.v2lapl2,
            p.v2lapltau,
            p.v2tau2,
            p.v3rho3,
            p.v3rho2sigma,
            p.v3rho2lapl,
            p.v3rho2tau,
            p.v3rhosigma2,
            p.v3rhosigmalapl,
            p.v3rhosigmatau,
            p.v3rholapl2,
            p.v3rholapltau,
            p.v3rhotau2,
            p.v3sigma3,
            p.v3sigma2lapl,
            p.v3sigma2tau,
            p.v3sigmalapl2,
            p.v3sigmalapltau,
            p.v3sigmatau2,
            p.v3lapl3,
            p.v3lapl2tau,
            p.v3lapltau2,
            p.v3tau3,
                s.param_BLOC_a,
            s.param_BLOC_b,
            s.param_b,
            s.param_c,
            s.param_e,
            s.param_kappa,
            s.param_mu,
            s.dens_threshold,
            s.zeta_threshold,
                lo,
                hi,
            );
        }
    });
}

